#!/usr/bin/env python3
"""Offline BGP relationship inference and route leak scoring service.

Protocol version 1, revision 1.  Reads one JSON document from stdin and writes
one JSON document to stdout; the exit status is always 0.

Pipeline: schema and bounds validation -> path normalization (IXP removal then
adjacent-duplicate collapse) -> weighted RIB aggregation -> simultaneous
peripheral peeling -> exact joint ternary model over core links (integer
potentials, variable elimination bounded by the supplied order) -> query
scoring with declaration/core/prior/uniform fallback in that precedence.
"""

import itertools
import json
import math
import re
import sys

MAX_INPUT_BYTES = 4194304
MAX_OUTPUT_BYTES = 16777216
MAX_ASN = 4294967295
MAX_WEIGHT = 1000000
MAX_RIB = 2000
MAX_PRIORS = 2000
MAX_DECLARED = 2000
MAX_QUERIES = 512
MAX_IXPS = 1024
MAX_RAW_PATH = 64
MAX_RIB_TOTAL = 40000
MAX_RIB_LINKS = 4096
MAX_CORE_LINKS = 64
MAX_ORDER = 5000
MAX_NEIGHBORS = 4

TOP_KEYS = ('version', 'ixps', 'rib', 'priors', 'declared', 'order', 'queries')
C2P, P2P, P2C = 0, 1, 2
STATES = (C2P, P2P, P2C)
REL_STATE = {'c2p': C2P, 'p2p': P2P, 'p2c': P2C}
# Preferred centre type g(L, R); rows are L, columns are R.
G_TABLE = ((C2P, C2P, P2P),
           (P2P, P2P, P2C),
           (P2P, P2P, P2C))
ID_RE = re.compile(r'\A[A-Za-z0-9_.\-]{1,64}\Z')


class Invalid(Exception):
    """Outside the published schema, bounds or order promise."""


class Broken(Exception):
    """Duplicate JSON keys, floats or constants: folded into Invalid."""


# ---------------------------------------------------------------------------
# reading and parsing
# ---------------------------------------------------------------------------
def read_all():
    stream = sys.stdin.buffer
    pieces = []
    total = 0
    stop = MAX_INPUT_BYTES + 1
    while total < stop:
        chunk = stream.read(min(1 << 16, stop - total))
        if not chunk:
            break
        pieces.append(chunk)
        total += len(chunk)
    if total > MAX_INPUT_BYTES:
        raise Invalid()
    return b''.join(pieces)


def object_hook(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            raise Broken()
        out[key] = value
    return out


def reject_number(text):
    raise Broken()


def reject_constant(text):
    raise Broken()


def parse(data):
    try:
        text = data.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid()
    try:
        return json.loads(text, object_pairs_hook=object_hook,
                          parse_float=reject_number,
                          parse_constant=reject_constant)
    except Broken:
        raise Invalid()
    except (ValueError, TypeError, RecursionError):
        raise Invalid()


# ---------------------------------------------------------------------------
# validation primitives
# ---------------------------------------------------------------------------
def expect_dict(obj):
    if type(obj) is not dict:
        raise Invalid()
    return obj


def expect_list(obj):
    if type(obj) is not list:
        raise Invalid()
    return obj


def exact_keys(record, names):
    obj = expect_dict(record)
    if len(obj) != len(names):
        raise Invalid()
    for name in names:
        if name not in obj:
            raise Invalid()
    return obj


def asn(value):
    if type(value) is not int or value < 1 or value > MAX_ASN:
        raise Invalid()
    return value


def weight(value, low):
    if type(value) is not int or value < low or value > MAX_WEIGHT:
        raise Invalid()
    return value


def raw_path(obj):
    items = expect_list(obj)
    if len(items) > MAX_RAW_PATH:
        raise Invalid()
    return [asn(v) for v in items]


def link_pair(obj):
    items = expect_list(obj)
    if len(items) != 2:
        raise Invalid()
    u = asn(items[0])
    v = asn(items[1])
    if u == v:
        raise Invalid()
    return (u, v)


def canonical(u, v):
    return (u, v) if u < v else (v, u)


def key_dir(u, v):
    """Canonical link plus True when the observed direction is canonical."""
    if u < v:
        return (u, v), True
    return (v, u), False


def normalize(raw, ixps):
    """Drop IXPs first, then collapse each maximal run of duplicates."""
    out = []
    for value in raw:
        if value in ixps:
            continue
        if out and out[-1] == value:
            continue
        out.append(value)
    return tuple(out), len(set(out)) != len(out)


# ---------------------------------------------------------------------------
# simultaneous peripheral peeling
# ---------------------------------------------------------------------------
def peel(paths):
    """paths: dict of directed normalized RIB path -> aggregated count."""
    rounds = {}
    current = dict(paths)
    step = 0
    while current:
        step += 1
        occ = {}
        for path in current:
            prev = path[0]
            for value in path[1:]:
                occ.setdefault(canonical(prev, value), []).append(path)
                prev = value
        marked = set()
        for link, plist in occ.items():
            u, v = link
            all_u = True
            all_v = True
            for path in plist:
                if path[0] != u and path[-1] != u:
                    all_u = False
                if path[0] != v and path[-1] != v:
                    all_v = False
                if not all_u and not all_v:
                    break
            if all_u or all_v:
                marked.add(link)
        if not marked:
            break
        for link in marked:
            rounds[link] = step
        nxt = {}
        for path, count in current.items():
            head_link = canonical(path[0], path[1])
            tail_link = canonical(path[-2], path[-1])
            trimmed = path
            if head_link in marked:
                trimmed = trimmed[1:]
            if tail_link in marked:
                trimmed = trimmed[:-1] if len(trimmed) > 1 else trimmed[:0]
            if len(trimmed) < 2:
                continue
            nxt[trimmed] = nxt.get(trimmed, 0) + count
        current = nxt
    return rounds, current


# ---------------------------------------------------------------------------
# core model potentials
# ---------------------------------------------------------------------------
class Model(object):
    """One ternary variable per canonical core link; occurrence contexts."""

    def __init__(self, core_links, finals):
        self.links = list(core_links)
        self.index = {}
        for i, link in enumerate(self.links):
            self.index[link] = i
        self.m = len(self.links)
        self.ctx = [[] for _ in range(self.m)]
        self.scopes = [None] * self.m
        self.patterns = [None] * self.m
        self._collect(finals)

    def _collect(self, finals):
        index = self.index
        for path, count in finals.items():
            n = len(path)
            rev = path[::-1]
            for i in range(n - 1):
                a = path[i]
                b = path[i + 1]
                if a < b:
                    link, seq, j = (a, b), path, i
                else:
                    link, seq, j = (b, a), rev, n - 2 - i
                e = index.get(link)
                if e is None:
                    raise Invalid()
                if j > 0:
                    left = self._var(index, seq[j - 1], a)
                else:
                    left = None
                if j + 2 < n:
                    right = self._var(index, b, seq[j + 2])
                else:
                    right = None
                self.ctx[e].append((left, right, count))

    @staticmethod
    def _var(index, u, v):
        link, forward = key_dir(u, v)
        var = index.get(link)
        if var is None:
            raise Invalid()
        return (var, forward)

    def _prepare(self):
        for e in range(self.m):
            seen = [False] * self.m
            seen[e] = True
            scope = [e]
            for left, right, _count in self.ctx[e]:
                for ctx in (left, right):
                    if ctx is not None and not seen[ctx[0]]:
                        seen[ctx[0]] = True
                        scope.append(ctx[0])
            self.scopes[e] = tuple(scope)
            pos = {}
            for i, var in enumerate(scope):
                pos[var] = i
            table = {}
            dims_cache = {}
            for left, right, count in self.ctx[e]:
                if left is None and right is not None:
                    dims = ((pos[right[0]], right[1]),)
                    shape = 1
                    lo = None
                    hi = 0
                elif left is not None and right is None:
                    dims = ((pos[left[0]], left[1]),)
                    shape = 1
                    lo = 0
                    hi = None
                elif left is None and right is None:
                    dims = ()
                    shape = 1
                    lo = None
                    hi = None
                else:
                    dims = ((pos[left[0]], left[1]), (pos[right[0]], right[1]))
                    shape = 2
                    lo = 0
                    hi = 1
                listed = dims_cache.get(shape if shape == 1 else 2)
                if listed is None:
                    listed = [list(item) for item in
                              itertools.product(STATES, repeat=shape)]
                    dims_cache[shape if shape == 1 else 2] = listed
                for values in listed:
                    if lo is None:
                        lv = C2P
                    else:
                        raw = values[lo]
                        lv = raw if left[1] else 2 - raw
                    if hi is None:
                        rv = P2C
                    else:
                        raw = values[hi]
                        rv = raw if right[1] else 2 - raw
                    g = G_TABLE[lv][rv]
                    key = tuple([(pos[e], g)] +
                                [(dims[i][0], values[i]) for i in range(shape)])
                    table[key] = table.get(key, 0) + count
            self.patterns[e] = table

    def build_phis(self):
        """Tables of the integer potentials phi_e over each declared scope."""
        self._prepare()
        phis = []
        for e in range(self.m):
            scope = self.scopes[e]
            k = len(scope)
            size = 3 ** k
            stride = [3 ** (k - 1 - i) for i in range(k)]
            values = [0] * size
            offsets = {}
            for key, count in self.patterns[e].items():
                fixed = 0
                used = []
                for position, value in key:
                    fixed += stride[position] * value
                    used.append(position)
                mask = tuple(sorted(used))
                free = offsets.get(mask)
                if free is None:
                    free = [0]
                    for i in range(k):
                        if i in mask:
                            continue
                        step = stride[i]
                        free = [f + t * step for f in free for t in STATES]
                    offsets[mask] = free
                for f in free:
                    values[fixed + f] += count
            phis.append((scope, values))
        return phis


# ---------------------------------------------------------------------------
# exact variable elimination over the ordered induced decomposition
# ---------------------------------------------------------------------------
def check_width(phis, order_vars):
    """order must be an elimination of the scope graph with width <= 4."""
    n = len(phis)
    adj = [set() for _ in range(n)]
    for scope, _values in phis:
        for i in range(len(scope)):
            for j in range(i + 1, len(scope)):
                a, b = scope[i], scope[j]
                adj[a].add(b)
                adj[b].add(a)
    for var in order_vars:
        neigh = adj[var]
        if len(neigh) > MAX_NEIGHBORS:
            raise Invalid()
        items = list(neigh)
        for other in items:
            adj[other].discard(var)
        for i in range(len(items)):
            for j in range(i + 1, len(items)):
                adj[items[i]].add(items[j])
                adj[items[j]].add(items[i])
        adj[var] = set()


def build_plan(phis, order_vars):
    """Elimination plan: pure structure, reusable for every clamp."""
    scopes = [list(scope) for scope, _values in phis]
    alive = [True] * len(scopes)
    steps = []
    for var in order_vars:
        involved = [fi for fi in range(len(scopes))
                    if alive[fi] and var in scopes[fi]]
        if not involved:
            continue
        union = []
        for fi in involved:
            for x in scopes[fi]:
                if x not in union:
                    union.append(x)
        others = [x for x in union if x != var]
        digits = [list(item) for item in
                  itertools.product(STATES, repeat=len(union))]
        ustr = [3 ** (len(union) - 1 - i) for i in range(len(union))]
        maps = []
        for fi in involved:
            scope = scopes[fi]
            fstr = [3 ** (len(scope) - 1 - i) for i in range(len(scope))]
            where = [union.index(x) for x in scope]
            table = []
            for d in digits:
                idx = 0
                for j, p in enumerate(where):
                    idx += d[p] * fstr[j]
                table.append(idx)
            maps.append((fi, table))
        ostr = [3 ** (len(others) - 1 - i) for i in range(len(others))]
        owere = [union.index(x) for x in others]
        outmap = []
        for d in digits:
            idx = 0
            for j, p in enumerate(owere):
                idx += d[p] * ostr[j]
            outmap.append(idx)
        for fi in involved:
            alive[fi] = False
        scopes.append(list(others))
        steps.append((maps, outmap, len(digits), len(others)))
    tail = [fi for fi in range(len(scopes)) if alive[fi]]
    return steps, tail


def run_plan(plan, phis, clamp=None):
    steps, tail = plan
    values = [list(v) for _scope, v in phis]
    if clamp is not None:
        var, state = clamp
        scope, _v = phis[var]
        row = values[var]
        if len(scope) == 1:
            if state != 0:
                row = [0, 0, 0]
            row = list(row)
            row[state] = phis[var][1][state]
            values[var] = row
        else:
            stride = 3 ** (len(scope) - 1 - scope.index(var))
            src = phis[var][1]
            row = [0] * len(src)
            for idx in range(len(src)):
                if (idx // stride) % 3 == state:
                    row[idx] = src[idx]
            values[var] = row
    for maps, outmap, size, nother in steps:
        out = [0] * (3 ** nother)
        if len(maps) == 1:
            fi, table = maps[0]
            src = values[fi]
            for j in range(size):
                x = src[table[j]]
                if x:
                    out[outmap[j]] += x
        else:
            srcs = [values[fi] for fi, _t in maps]
            tbls = [t for _fi, t in maps]
            width = len(srcs)
            for j in range(size):
                prod = 1
                for k in range(width):
                    prod *= srcs[k][tbls[k][j]]
                    if not prod:
                        break
                if prod:
                    out[outmap[j]] += prod
        values.append(out)
    result = 1
    for fi in tail:
        for x in values[fi]:
            result *= x
    return result


def marginal_rows(phis, order_vars):
    """Exact numerators and common denominator Z for every core variable."""
    plan = build_plan(phis, order_vars)
    total = run_plan(plan, phis)
    if total == 0:
        return None
    n = len(phis)
    touched = [set() for _ in range(n)]
    for e in range(n):
        scope = phis[e][0]
        for var in scope:
            touched[var].add(e)
    rows = [None] * n
    for var in range(n):
        scope = phis[var][0]
        if len(scope) == 1 and len(touched[var]) == 1:
            row = phis[var][1]
            s = row[0] + row[1] + row[2]
            if s > 0:
                rows[var] = (row[0], row[1], row[2], s)
                continue
        first = run_plan(plan, phis, (var, C2P))
        second = run_plan(plan, phis, (var, P2P))
        third = total - first - second
        if third < 0:
            third = 0
        rows[var] = (first, second, third, total)
    return rows


# ---------------------------------------------------------------------------
# query scoring
# ---------------------------------------------------------------------------
def triple_legitimacy(left, right):
    nu, du = left[C2P]
    nd, dd = right[P2C]
    num = nu * dd + nd * du - nu * nd
    if num <= 0:
        return (0, 1)
    den = du * dd
    g = math.gcd(num, den)
    return (num // g, den // g)


def full_legitimacy(vectors):
    """Sum of products over c2p* p2c* and c2p* p2p p2c*, as a float."""
    state_c = 1.0
    state_d = 0.0
    state_p = 0.0
    for vec in vectors:
        pc = vec[C2P][0] / vec[C2P][1]
        pp = vec[P2P][0] / vec[P2P][1]
        pd = vec[P2C][0] / vec[P2C][1]
        state_c, state_d, state_p = (state_c * pc,
                                     (state_c + state_d) * pd,
                                     state_c * pp + state_p * pd)
    out = state_c + state_d + state_p
    if not math.isfinite(out) or out < 0.0:
        return 0.0
    return 1.0 if out > 1.0 else out


def one_hot(state, forward):
    vec = [(0, 1), (0, 1), (0, 1)]
    vec[state] = (1, 1)
    if not forward:
        vec = (vec[2], vec[1], vec[0])
    else:
        vec = tuple(vec)
    return vec


def lookup(link, forward, declared, marginals, priors):
    vec = declared.get(link)
    if vec is None:
        mar = marginals.get(link)
        if mar is not None:
            n0, n1, n2, den = mar
            vec = ((n0, den), (n1, den), (n2, den))
        else:
            vec = priors.get(link)
            if vec is None:
                vec = ((1, 3), (1, 3), (1, 3))
    return vec if forward else (vec[2], vec[1], vec[0])


def finite(value):
    if not isinstance(value, float) or not math.isfinite(value):
        return 0.0
    return value


# ---------------------------------------------------------------------------
# request handling
# ---------------------------------------------------------------------------
def solve(document):
    obj = expect_dict(document)
    if len(obj) != len(TOP_KEYS):
        raise Invalid()
    for name in TOP_KEYS:
        if name not in obj:
            raise Invalid()
    if type(obj['version']) is not int or obj['version'] != 1:
        raise Invalid()

    raw_ixps = expect_list(obj['ixps'])
    if len(raw_ixps) > MAX_IXPS:
        raise Invalid()
    ixps = set()
    for value in raw_ixps:
        v = asn(value)
        if v in ixps:
            raise Invalid()
        ixps.add(v)

    raw_rib = expect_list(obj['rib'])
    if len(raw_rib) > MAX_RIB:
        raise Invalid()
    rib_records = []
    total_len = 0
    for record in raw_rib:
        item = exact_keys(record, ('path', 'count'))
        path = raw_path(item['path'])
        total_len += len(path)
        if total_len > MAX_RIB_TOTAL:
            raise Invalid()
        rib_records.append((path, weight(item['count'], 1)))

    raw_priors = expect_list(obj['priors'])
    if len(raw_priors) > MAX_PRIORS:
        raise Invalid()
    priors = {}
    for record in raw_priors:
        item = exact_keys(record, ('link', 'weights'))
        u, v = link_pair(item['link'])
        vals = expect_list(item['weights'])
        if len(vals) != 3:
            raise Invalid()
        w = [weight(x, 0) for x in vals]
        s = w[0] + w[1] + w[2]
        if s <= 0:
            raise Invalid()
        link = canonical(u, v)
        if link in priors:
            raise Invalid()
        vec = ((w[0], s), (w[1], s), (w[2], s))
        priors[link] = vec if u < v else (vec[2], vec[1], vec[0])

    raw_declared = expect_list(obj['declared'])
    if len(raw_declared) > MAX_DECLARED:
        raise Invalid()
    declared = {}
    for record in raw_declared:
        item = exact_keys(record, ('link', 'rel'))
        u, v = link_pair(item['link'])
        rel = item['rel']
        if type(rel) is not str or rel not in REL_STATE:
            raise Invalid()
        link = canonical(u, v)
        if link in declared:
            raise Invalid()
        declared[link] = one_hot(REL_STATE[rel], u < v)

    raw_order = expect_list(obj['order'])
    if len(raw_order) > MAX_ORDER:
        raise Invalid()
    order_links = []
    for item in raw_order:
        link = link_pair(item)
        if link[0] >= link[1]:
            raise Invalid()
        order_links.append(link)
    if len(set(order_links)) != len(order_links):
        raise Invalid()

    raw_queries = expect_list(obj['queries'])
    if len(raw_queries) > MAX_QUERIES:
        raise Invalid()
    queries = []
    ids = set()
    for record in raw_queries:
        item = exact_keys(record, ('id', 'path', 'threshold'))
        ident = item['id']
        if type(ident) is not str or not ID_RE.match(ident) or ident in ids:
            raise Invalid()
        ids.add(ident)
        path = raw_path(item['path'])
        thr = expect_list(item['threshold'])
        if len(thr) != 2 or type(thr[0]) is not int or type(thr[1]) is not int:
            raise Invalid()
        a, b = thr[0], thr[1]
        if a < 0 or b < 1 or a > MAX_WEIGHT or b > MAX_WEIGHT or a > b:
            raise Invalid()
        queries.append((ident, path, a, b))

    # ---- normalization and aggregation of the RIB ----
    agg = {}
    for path, count in rib_records:
        norm, looped = normalize(path, ixps)
        if looped or len(norm) < 2:
            continue
        agg[norm] = agg.get(norm, 0) + count

    all_links = set()
    for path in agg:
        prev = path[0]
        for value in path[1:]:
            all_links.add(canonical(prev, value))
            prev = value
    if len(all_links) > MAX_RIB_LINKS:
        raise Invalid()

    # ---- peeling ----
    rounds, finals = peel(agg)
    core_links = sorted(all_links - set(rounds))
    if len(core_links) > MAX_CORE_LINKS:
        raise Invalid()
    if len(order_links) != len(core_links) or set(order_links) != set(core_links):
        raise Invalid()

    # ---- exact joint inference ----
    marginals = {}
    if core_links:
        model = Model(core_links, finals)
        phis = model.build_phis()
        order_vars = [model.index[link] for link in order_links]
        check_width(phis, order_vars)
        rows = marginal_rows(phis, order_vars)
        if rows is None:
            return {'error': 'zero-partition'}
        for i, link in enumerate(model.links):
            marginals[link] = rows[i]

    # ---- link records ----
    links_out = []
    for link in sorted(all_links):
        rnd = rounds.get(link, 0)
        if rnd == 0:
            n0, n1, n2, den = marginals[link]
            prob = [finite(n0 / den), finite(n1 / den), finite(n2 / den)]
        else:
            vec = priors.get(link)
            if vec is None:
                prob = [1.0 / 3.0, 1.0 / 3.0, 1.0 / 3.0]
            else:
                prob = [finite(vec[0][0] / vec[0][1]),
                        finite(vec[1][0] / vec[1][1]),
                        finite(vec[2][0] / vec[2][1])]
        links_out.append({'link': [link[0], link[1]], 'round': rnd,
                          'prob': prob})

    # ---- query records ----
    queries_out = []
    for ident, raw, a, b in queries:
        norm, looped = normalize(raw, ixps)
        record = {'id': ident, 'path': list(norm), 'status': 'ok',
                  'score': None, 'full': None, 'witness': None,
                  'leaked': None}
        if looped:
            record['status'] = 'loop'
            queries_out.append(record)
            continue
        n = len(norm)
        if n < 3:
            record['score'] = 1.0
            record['full'] = 1.0
            record['leaked'] = False
            queries_out.append(record)
            continue
        vectors = []
        for i in range(n - 1):
            link, forward = key_dir(norm[i], norm[i + 1])
            vectors.append(lookup(link, forward, declared, marginals, priors))
        best = None
        best_index = 0
        for i in range(n - 2):
            value = triple_legitimacy(vectors[i], vectors[i + 1])
            if best is None or value[0] * best[1] < best[0] * value[1]:
                best = value
                best_index = i
        record['score'] = finite(best[0] / best[1])
        record['full'] = finite(full_legitimacy(vectors))
        record['witness'] = best_index
        record['leaked'] = best[0] * b < a * best[1]
        queries_out.append(record)

    return {'version': 1, 'links': links_out, 'queries': queries_out}


def emit(document):
    try:
        text = json.dumps(document, allow_nan=False, separators=(',', ':'))
    except (TypeError, ValueError, OverflowError):
        text = '{"error":"invalid"}'
    if len(text.encode('utf-8')) > MAX_OUTPUT_BYTES:
        text = '{"error":"invalid"}'
